import java.awt.event.MouseEvent;

public class DragBoxTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void press(DragBox panel, int x, int y) {
        panel.dispatchEvent(new MouseEvent(panel, MouseEvent.MOUSE_PRESSED,
                System.currentTimeMillis(), 0, x, y, 1, false));
    }

    static String offsets(DragBox panel) {
        return panel.getOffsetX() + "," + panel.getOffsetY();
    }

    static void drag(DragBox panel, int x, int y) {
        panel.dispatchEvent(new MouseEvent(panel, MouseEvent.MOUSE_DRAGGED,
                System.currentTimeMillis(), 0, x, y, 0, false));
    }

    public static void main(String[] args) {
        try {
            DragBox panel = new DragBox();
            check("a MouseMotionListener is registered", true,
                    panel.getMouseMotionListeners().length >= 1);
            check("offsets start at 0", "0,0", offsets(panel));

            press(panel, 50, 50);
            check("pressing alone moves nothing", "0,0", offsets(panel));

            drag(panel, 60, 55);
            check("offsetX after first drag", 10, panel.getOffsetX());
            check("offsetY after first drag", 5, panel.getOffsetY());

            drag(panel, 65, 45);
            check("offsetX after second drag", 15, panel.getOffsetX());
            check("offsetY after second drag", -5, panel.getOffsetY());

            // A new press re-anchors but keeps the running totals.
            press(panel, 100, 100);
            drag(panel, 90, 100);
            check("offsets after a re-anchored drag", "5,-5", offsets(panel));
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected " + t.getClass().getSimpleName() + ": " + t.getMessage());
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

